import numpy as np
from itertools import product

def get_max_k(N, s):
    M = N - s + 1
    tiles = []
    for r in range(M):
        for c in range(M):
            tile = np.zeros((N, N), dtype=int)
            tile[r:r+s, c:c+s] = 1
            tiles.append(tile)

    num_tiles = len(tiles)
    max_k = 0
    for combo in product([0, 1], repeat=num_tiles):
        board = np.zeros((N, N), dtype=int)
        for i in range(num_tiles):
            if combo[i]:
                board += tiles[i]

        nonzero_counts = []
        # We only care about m > 0
        for m in range(1, int(np.max(board)) + 1):
            count = np.sum(board == m)
            if count > 0:
                nonzero_counts.append(count)

        if nonzero_counts:
            max_k = max(max_k, max(nonzero_counts))

    return max_k

print(f"N=3, s=2: {get_max_k(3, 2)}")
print(f"N=4, s=2: {get_max_k(4, 2)}")
print(f"N=5, s=2: {get_max_k(5, 2)}")

